import java.io.*;
import java.util.*;

public class Solution {
    static class StreamHelper {
        BufferedReader br;
        StringTokenizer st;

        StreamHelper() {
            br = new BufferedReader(new InputStreamReader(System.in));
            st = null;
        }

        String getToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (IOException e) {
                    System.out.println(e);
                }
            }
            return st.nextToken();
        }

        int getInt() {
            return Integer.parseInt(getToken());
        }

        long getLong() {
            return Long.parseLong(getToken());
        }

        double getDouble() {
            return Double.parseDouble(getToken());
        }

        String getLine() {
            try {
                if (st == null || !st.hasMoreTokens()) {
                    st = new StringTokenizer(br.readLine());
                }
            } catch (IOException e) {
                System.out.println(e);
            }
            return st.nextToken("\n");
        }
    }

    static final long MOD = 998244353L;
    static final int MAXN = 200005;
    static long[] factArray = new long[MAXN];

    static long powerMod(long base, long exp, long mod) {
        long res = 1L;
        while (exp > 0) {
            if ((exp & 1) == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return res;
    }

    static long nCr(int n, int r) {
        if (r > n) return 0L;
        return factArray[n] * powerMod(factArray[r], MOD - 2, MOD) % MOD * powerMod(factArray[n - r], MOD - 2, MOD) % MOD;
    }

    static long calculateSum(int n, int k) {
        long total = 0;
        for (int i = 0; i <= n - k; i++) {
            long val = nCr(n - k, i) * powerMod(n - k - i, n, MOD) % MOD;
            if (i % 2 == 0) total = (total + val) % MOD;
            else total = (total - val + MOD) % MOD;
        }
        return total;
    }

    public static void main(String[] args) {
        StreamHelper sh = new StreamHelper();
        int t = 1;
        // t = sh.getInt();
        for (int q = 0; q < t; q++) {
            long n = sh.getLong();
            long k = sh.getLong();
            factArray[0] = 1;
            for (long i = 1; i <= n; i++) {
                factArray[(int) i] = factArray[(int) (i - 1)] * i % MOD;
            }
            if (k >= n) {
                System.out.println(0);
            } else if (k == 0) {
                System.out.println(factArray[(int) n]);
            } else {
                long res = 2 * nCr((int) n, (int) (n - k)) * calculateSum((int) n, (int) k) % MOD;
                System.out.println(res);
            }
        }
    }
}
