#include <bits/stdc++.h>
using namespace std;

struct StreamHelper {
    std::istream& in;
    std::string token;
    std::stringstream ss;

    StreamHelper(std::istream& input) : in(input) {}

    std::string getToken() {
        while (ss.rdbuf()->in_avail() == 0) {
            std::string line;
            if (!std::getline(in, line)) {
                return "";
            }
            ss.clear();
            ss.str(line);
        }
        ss >> token;
        return token;
    }

    int getInt() {
        getToken();
        return std::stoi(token);
    }

    long long getLong() {
        getToken();
        return std::stoll(token);
    }

    double getDouble() {
        getToken();
        return std::stod(token);
    }

    std::string getLine() {
        std::string line;
        std::getline(in, line);
        return line;
    }
};

